ironpython_path_stubs = {
    "ProgramFilesPath": [r'C:\Program Files', r'C:\Program Files (x86)'],
    "IronPython": ['IronPython 2.7'],
    "IpyExecutable": ['ipy.exe', 'ipy32.exe'],
    "_binary_preference": 'ipy32'
}


def return_ironpython_path():
    _path = [ipy_path for ipy_path in
             ["\\".join([x, y, z]) for x in ironpython_path_stubs['ProgramFilesPath'] for y in
              ironpython_path_stubs['IronPython'] for
              z in ironpython_path_stubs['IpyExecutable']] if
             path.isfile(ipy_path)]
    try:
        return _path.pop(_path.index([i for i in _path if search(ironpython_path_stubs["_binary_preference"], i)][0]))
    except IndexError:
        return _path.pop()
